input.content:
/* B"H — mobile panels: reachable rows, never off-canvas */
@media (max-width: 680px) {
  .sidebar,
  .automation-panel {
    display: grid !important;
    position: relative !important;
    inset: auto !important;
    left: auto !important;
    right: auto !important;
    min-width: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    border-radius: 18px !important;
    overflow: hidden !important;
    z-index: 1 !important;
    transform: none !important;
  }

  .sidebar {
    grid-area: left !important;
    max-height: 78px !important;
    grid-template-rows: 70px minmax(0, 1fr) !important;
  }

  .automation-panel {
    grid-area: right !important;
    max-height: 82px !important;
    grid-template-rows: 72px minmax(0, 1fr) !important;
  }

  body:not([data-sidebar-collapsed="true"]) .sidebar {
    max-height: min(42dvh, 360px) !important;
  }

  body:not([data-automation-collapsed="true"]) .automation-panel {
    max-height: min(48dvh, 420px) !important;
  }

  .panel-topbar,
  .sidebar-header {
    min-height: 68px !important;
    width: 100% !important;
    min-width: 0 !important;
    padding: 10px 12px !important;
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    overflow: hidden !important;
  }

  .panel-topbar h2,
  .sidebar-header h2 {
    min-width: 0 !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
  }

  .sidebar::before,
  .automation-panel::before {
    writing-mode: horizontal-tb !important;
    transform: none !important;
    position: static !important;
    max-width: 100% !important;
  }

  .conversation-list,
  .automation-panel > :not(.panel-topbar) {
    min-height: 0 !important;
    max-width: 100% !important;
    overflow: auto !important;
    padding: 10px !important;
  }

  body[data-sidebar-collapsed="true"] .conversation-list,
  body[data-automation-collapsed="true"] .automation-panel > :not(.panel-topbar) {
    display: none !important;
  }

  body[data-sidebar-collapsed="true"] .sidebar,
  body[data-automation-collapsed="true"] .automation-panel {
    max-height: 72px !important;
  }

  .panel-action-rail,
  .panel-corner-actions,
  .event-panel-actions {
    position: static !important;
    transform: none !important;
    max-width: 100% !important;
  }

  .right-tabs {
    overflow-x: auto !important;
    flex-wrap: nowrap !important;
    max-width: 100% !important;
    scrollbar-width: thin;
  }

  .right-tabs button {
    flex: 0 0 auto !important;
    min-width: 100px !important;
  }

  .automation-field,
  .graph-node,
  .graph-canvas {
    max-width: 100% !important;
    min-width: 0 !important;
  }
}
